-- Generated by ekos-lakehouse (RFC 0195): the mart's revenue total equals silver's.
select 1 from (select sum("revenue") as m from {{ ref('gold__rentals_by_customer_month') }}) a
cross join (select sum("payment"."amount") as s from {{ ref('public__payment') }} as "payment") b
where abs(coalesce(a.m,0) - coalesce(b.s,0)) > 0.005
